'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),os=require('node:os'),path=require('node:path');
const {validateFeed,publicUrl,officialUrl,mondayEditionDue,staleFeed}=require('../drop-news-core');const {createNewsService,register}=require('../drop-news-service');
const stamp='2026-10-20T12:00:00.000Z';
const fixture=()=>({schema:1,publishedAt:stamp,summary:'Public news only',retailers:['target','walmart','pokemoncenter','costco','sams'].map(id=>({id,coverage:'Checked official sources',checks:['Verify the product page'],confirmed:[]})),rumors:[]});
const item=(url='https://www.target.com/p/tcg/-/A-123')=>({title:'Example listing',kind:'listing',details:'A listing is not a drop time.',sources:[{title:'Official listing',url,checkedAt:stamp}]});
test('five retailer sections required; official sources cannot be spoofed',()=>{const feed=fixture();feed.retailers[0].confirmed=[item()];assert.equal(validateFeed(feed).retailers.length,5);assert.equal(officialUrl('https://target.com.attacker.org/','target'),false);assert.equal(officialUrl('https://www.costco.com/item','costco'),true);assert.equal(officialUrl('https://help.samsclub.com/','sams'),true);feed.retailers[0].confirmed=[item('https://news.example.org/article')];assert.throws(()=>validateFeed(feed),/official/);assert.throws(()=>validateFeed({...fixture(),retailers:fixture().retailers.slice(0,4)}),/coverage/);});
test('unsafe links and unchecked sources are excluded',()=>{for(const u of ['javascript:alert(1)','http://target.com','https://localhost/x','https://127.0.0.1/x','https://[::1]/','https://user:pw@target.com'])assert.equal(publicUrl(u),null);const f=fixture();f.retailers[0].confirmed=[{...item(),sources:[{url:'https://target.com',checkedAt:''}]}];assert.throws(()=>validateFeed(f),/checked sources/);});
test('rumors remain separate and never enter confirmed sections',()=>{const f=fixture();f.rumors=[{retailer:'costco',...item('https://news.example.org/article')}];assert.equal(validateFeed(f).rumors[0].kind,'rumor');assert.equal(validateFeed(f).retailers[3].confirmed.length,0);});
test('weekly staleness uses New York Monday 8am including DST',()=>{assert.equal(new Date(mondayEditionDue(new Date('2026-10-26T11:59:00Z'))).toISOString(),'2026-10-19T12:00:00.000Z');assert.equal(new Date(mondayEditionDue(new Date('2026-10-26T12:00:00Z'))).toISOString(),'2026-10-26T12:00:00.000Z');assert.equal(new Date(mondayEditionDue(new Date('2026-11-02T13:00:00Z'))).toISOString(),'2026-11-02T13:00:00.000Z');assert.equal(staleFeed(fixture(),new Date('2026-10-26T13:00:00Z')),true);});
test('concurrent reads deduplicate; offline and invalid updates preserve last good cache',async t=>{const dir=await fs.mkdtemp(path.join(os.tmpdir(),'aco-news-'));t.after(()=>fs.rm(dir,{recursive:true,force:true}));let requests=0,fail=false,now=new Date(stamp);const f=fixture();f.retailers[0].confirmed=[item()];const service=createNewsService({cacheFile:path.join(dir,'cache.json'),now:()=>now,request:async()=>{requests++;await new Promise(r=>setTimeout(r,5));if(fail)throw Error('offline');return f;}});await Promise.all([service.read(),service.read()]);assert.equal(requests,1);assert.equal(service.sourceAllowed('https://www.target.com/p/tcg/-/A-123'),true);assert.equal(service.sourceAllowed('https://target.com/unlisted'),false);fail=true;now=new Date(+now+61000);const cached=await service.read();assert.equal(cached.cached,true);assert.equal(cached.feed.summary,'Public news only');assert.ok(cached.error);const restart=createNewsService({cacheFile:path.join(dir,'cache.json'),request:async()=>({schema:2}),now:()=>now});assert.equal((await restart.read()).feed.summary,'Public news only');});
test('IPC enforces owner sender for reads and source opens',async()=>{const handlers=new Map();register({app:{getPath:()=>os.tmpdir()},ipcMain:{handle:(key,fn)=>handlers.set(key,fn)},requireOwner:()=>{throw Error('unauthorized');},shell:{openExternal:()=>{throw Error('must not open');}}});assert.throws(()=>handlers.get('drop-news:read')({}),/unauthorized/);await assert.rejects(handlers.get('drop-news:source')({},'https://target.com'),/unauthorized/);});
